import { withAdminErrorBoundary, requirePermission, okResponse, errorResponse, resultErrorResponse } from '@/lib/admin/authz';
import { PERMISSIONS } from '@/lib/admin/permissions';
import { checkIdempotency, completeIdempotency, getRequiredIdempotencyKey, releaseIdempotency } from '@/lib/admin/idempotency';
import { setPrimaryProvider } from '@/lib/services/modelRouting';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/**
 * 切换模型的默认供应商渠道。高风险写：必须带 Idempotency-Key，
 * 与 PATCH /api/admin/models/[id] 同一套防重放约定。
 */
async function handlePATCH(request, context) {
  const guard = await requirePermission(request, PERMISSIONS.modelsWrite);
  if (!guard.ok) return guard.response;

  const idempotencyKey = getRequiredIdempotencyKey(request);
  if (!idempotencyKey) return errorResponse('VALIDATION_ERROR', '高风险写操作必须提供有效的 Idempotency-Key', 422, guard.requestId);
  const idemp = await checkIdempotency({ scope: 'model_provider_switch', key: idempotencyKey, actorId: guard.user.id });
  if (!idemp.allowed) {
    if (idemp.cachedResponse) return okResponse(idemp.cachedResponse, guard.requestId);
    return errorResponse('CONFLICT', '默认供应商切换正在处理中', 409, guard.requestId);
  }

  const { id } = await context.params;
  const body = await request.json().catch(() => ({}));
  const channelId = body.channelId || body.channel_id;

  const result = await setPrimaryProvider({
    actor: guard.user,
    modelId: id,
    channelId,
    requestId: guard.requestId,
  });

  if (result.error) {
    await releaseIdempotency(idemp.keyHash);
    return resultErrorResponse(result.error, guard.requestId);
  }

  await completeIdempotency(idemp.keyHash, result.model);
  return okResponse(result.model, guard.requestId);
}

export const PATCH = withAdminErrorBoundary(handlePATCH);

import { withAdminErrorBoundary, requirePermission, okResponse, errorResponse } from '@/lib/admin/authz';
import { PERMISSIONS } from '@/lib/admin/permissions';
import {
  getBrandModelsPageData,
  bindBrandModel,
  toggleChannelModel,
  updateChannelPriority,
  unbindChannelModel,
} from '@/lib/services/modelBrands.js';
import { logAudit } from '@/lib/admin/audit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

async function handleGET(request) {
  const guard = await requirePermission(request, PERMISSIONS.modelsRead);
  if (!guard.ok) return guard.response;

  const { searchParams } = new URL(request.url);
  const providerId = searchParams.get('provider') || null;

  const data = await getBrandModelsPageData({ providerId });
  return okResponse(data, guard.requestId);
}

async function handlePOST(request) {
  const guard = await requirePermission(request, PERMISSIONS.modelsWrite);
  if (!guard.ok) return guard.response;

  const body = await request.json().catch(() => ({}));
  const action = body.action || 'bind';

  if (action === 'toggle') {
    const { channelId, enabled } = body;
    if (!channelId) {
      return errorResponse('VALIDATION_ERROR', '缺少 channelId 参数', 422, guard.requestId);
    }
    const result = await toggleChannelModel(channelId, enabled);
    await logAudit({
      actor: guard.user,
      action: 'provider_models.toggle',
      targetType: 'provider_model',
      targetId: channelId,
      riskLevel: 'medium',
      after: { enabled },
    });
    return okResponse(result, guard.requestId);
  }

  if (action === 'priority') {
    const { channelId, priority } = body;
    if (!channelId) {
      return errorResponse('VALIDATION_ERROR', '缺少 channelId 参数', 422, guard.requestId);
    }
    const result = await updateChannelPriority(channelId, priority);
    await logAudit({
      actor: guard.user,
      action: 'provider_models.update_priority',
      targetType: 'provider_model',
      targetId: channelId,
      riskLevel: 'low',
      after: { priority },
    });
    return okResponse(result, guard.requestId);
  }

  if (action === 'unbind') {
    const { channelId } = body;
    if (!channelId) {
      return errorResponse('VALIDATION_ERROR', '缺少 channelId 参数', 422, guard.requestId);
    }
    const result = await unbindChannelModel(channelId);
    await logAudit({
      actor: guard.user,
      action: 'provider_models.unbind',
      targetType: 'provider_model',
      targetId: channelId,
      riskLevel: 'high',
      before: { channelId },
    });
    return okResponse(result, guard.requestId);
  }

  // 默认：挂载品牌模型
  const { providerId, modelId, providerModelId, priority, baseCost, currency, providerEndpoint, enabled } = body;
  if (!providerId || !modelId || !providerModelId) {
    return errorResponse('VALIDATION_ERROR', '供应商 ID、规范模型 ID 与渠道内部模型标识均为必填项', 422, guard.requestId);
  }

  const result = await bindBrandModel({
    providerId,
    modelId,
    providerModelId,
    priority: Number(priority ?? 100),
    baseCost: Number(baseCost ?? 0.01),
    currency: currency || 'USD',
    providerEndpoint: providerEndpoint || '',
    enabled: enabled !== false,
  });

  await logAudit({
    actor: guard.user,
    action: 'provider_models.bind_brand_model',
    targetType: 'provider_model',
    targetId: result.id,
    riskLevel: 'medium',
    after: result,
  });

  return okResponse(result, guard.requestId);
}

export const GET = withAdminErrorBoundary(handleGET);
export const POST = withAdminErrorBoundary(handlePOST);

